head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf00100";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf00100.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $('#paging7 table:first-child').attr('align', 'center');

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf00100.onpageload' }); }
};

// [A] 초기 목록 미해결 — 같은 액션인데 method 가 3개다(notice#searchnoticelist vs notice#searchnoticespec vs notice#downloadfile) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_srchWord_onkeydown
 * @description ipt_srchWord 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_srchWord_onkeydown = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        if(event.keyCode===13){$c.str.replaceAll(selfVar);await scwin.searchNoticeListByCond();}

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf00100.ipt_srchWord_onkeydown' }); }
};

/**
 * @method
 * @name ipt_srchWord_onblur
 * @description ipt_srchWord 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_srchWord_onblur = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        $c.str.replaceAll(selfVar);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf00100.ipt_srchWord_onblur' }); }
};

/**
 * @method
 * @name btn_searchNoticeListByCond_onclick
 * @description btn_searchNoticeListByCond 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchNoticeListByCond_onclick = async function(e){
    try {
        await scwin.searchNoticeListByCond()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf00100.btn_searchNoticeListByCond_onclick' }); }
};

/**
 * @method
 * @name grd_result_oncellclick
 * @description grd_result 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_result_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_result */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["attachFileNm"] !== '') { await scwin.fileDown(r["contnId"], r["attachFileNm"]); return; }
        await scwin.searchNoticeSpec(r["contnId"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_result.oncellclick' });
    }
};

/**
 * @method
 * @name span_52_onclick
 * @description 「닫 기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.span_52_onclick = function(e){
    try {
        scwin.close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf00100.span_52_onclick' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_48_onclick
 * @description krxpage_pagenavigator_48 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_48_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_searchNoticeListByCondReq').set('pageIndex', pi);
        await scwin.searchNoticeListByCond();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldbnf00100.krxpage_pagenavigator_48_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchNoticeListByCond
 * @description search Notice List By Cond 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchNoticeListByCond = async function () {
    const sbmOptions = {
        id: "tx_fn_searchNoticeListByCond",
        method: "post",
        action: "/main/notice.do?method=searchNoticeList",
        ref: "dma_searchNoticeListByCondReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_searchNoticeSpec
 * @description search Notice Spec 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchNoticeSpec = async function () {
    const sbmOptions = {
        id: "tx_fn_searchNoticeSpec",
        method: "post",
        action: "/main/notice.do?method=searchNoticeSpec",
        ref: "dma_searchNoticeSpecReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPageIndex
 * @description init Page Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPageIndex = function () {
    $c.util.getComponent('dma_searchNoticeListByCondReq').set('pageIndex', "1");
};

/**
 * @method
 * @name tx_fn_fileDown
 * @description file Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_fileDown = async function () {
    try { return await $c.data.downFile("/main/notice.do?method=downloadFile", "", ($c.util.getComponent("dma_fileDownReq") ? $c.util.getComponent("dma_fileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name grd_result_fmt_attachFileNm
 * @description grd result fmt attach File Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_result_fmt_attachFileNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_result");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "attachFileNm") ?? '') : '');
        if (v !== '') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + "첨부파일" + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_result.attachFileNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name searchNoticeListByCond
 * @description search Notice List By Cond 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchNoticeListByCond = async function () {
    const width = 670;
    const height = 500;
    const mtWidth = document.body.clientWidth;
    const mtHeight = document.body.clientHeight;
    const scX = 0;
    const scY = 0;
    const popX = scX + (mtWidth - width) / 2;
    const popY = scY + (mtHeight - height) / 2;
    let _previewWindow;
    _previewWindow = $c.win.openPopup("/notice/notice.xml", { id: "popNoticeList", resizable: false, scrollbars: true, type: "pageFramePopup" }, ($c.util.getComponent("dma_searchNoticeListByCondReq") ? $c.util.getComponent("dma_searchNoticeListByCondReq").getJSON() : {}));
    const srchDiv = $("#srchDiv option:selected").val();
    const fm = (document.searchForm || { elements: [] });
    $c.util.getComponent("dma_searchNoticeListByCondReq").set("srchDiv", srchDiv);
    fm.action = '/main/notice.do?method=searchNoticeList';

    return;
};

/**
 * @method
 * @name searchNoticeSpec
 * @description search Notice Spec 처리
 * @param {String} contnId contnId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchNoticeSpec = async function (contnId) {
    const fm = (document.searchForm || { elements: [] });
    $c.util.getComponent('dma_searchNoticeListByCondReq').set('contnId', contnId);
    fm.action = '/main/notice.do?method=searchNoticeSpec';
    await scwin.tx_fn_searchNoticeSpec();
    return;
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {String} contnId contnId
 * @param {String} attachFileNm attachFileNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDown = async function (contnId, attachFileNm) {
    if (attachFileNm == null || attachFileNm === "") {
        await $c.win.alert("첨부파일이 없습니다.");
        return;
    }
    const fm = (document.searchForm || { elements: [] });
    $c.util.getComponent('dma_searchNoticeListByCondReq').set('contnId', contnId);
    fm.action = '/main/notice.do?method=downloadFile';
    await scwin.tx_fn_fileDown();
    return;
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    $c.win.closePopup();
};
